import { useState } from "react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { GripVertical, Plus, MoreHorizontal, Flag } from "lucide-react";
import { Button } from "@/components/ui/button";
import TaskDetailModal from "./TaskDetailModal";
import type { Task as TaskDetailType } from "./TaskDetailModal";

interface Task {
  id: string;
  title: string;
  type: "epic" | "story" | "subtask";
  status: "backlog" | "todo" | "in_progress" | "review" | "done";
  priority: "low" | "medium" | "high";
  storyPoints?: number;
  assignee?: string;
  aiGenerated?: boolean;
}

interface EnhancedKanbanBoardProps {
  projectId: string;
  tasks: Task[];
}

export default function EnhancedKanbanBoard({ projectId, tasks }: EnhancedKanbanBoardProps) {
  const [selectedTask, setSelectedTask] = useState<TaskDetailType | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const columns: Array<{ 
    id: Task["status"]; 
    title: string;
  }> = [
    { id: "backlog", title: "Backlog" },
    { id: "todo", title: "To Do" },
    { id: "in_progress", title: "In Progress" },
    { id: "review", title: "Review" },
    { id: "done", title: "Done" },
  ];

  const handleTaskClick = (task: Task) => {
    setSelectedTask({
      ...task,
      key: `${projectId}-${task.id}`,
      description: "This task was generated by AI to help you build your project.",
      reporter: "System",
      labels: task.aiGenerated ? ["AI-Generated"] : [],
      createdAt: "2 days ago",
      updatedAt: "1 hour ago",
      priority: task.priority as TaskDetailType["priority"],
    });
    setIsModalOpen(true);
  };

  const getColumnTasks = (status: Task["status"]) => 
    tasks.filter((task) => task.status === status);

  const typeConfig: Record<Task["type"], { className: string; label: string }> = {
    epic: { 
      className: "bg-[hsl(var(--lozenge-blocked-bg))] text-[hsl(var(--lozenge-blocked))] border-[hsl(var(--lozenge-blocked))]", 
      label: "Epic" 
    },
    story: { 
      className: "bg-[hsl(var(--lozenge-todo-bg))] text-[hsl(var(--lozenge-todo))] border-[hsl(var(--lozenge-todo))]", 
      label: "Story" 
    },
    subtask: { 
      className: "bg-[hsl(var(--lozenge-low-bg))] text-[hsl(var(--lozenge-low))] border-[hsl(var(--lozenge-low))]", 
      label: "Subtask" 
    },
  };

  const priorityColors: Record<string, string> = {
    low: "text-[hsl(var(--lozenge-low))]",
    medium: "text-[hsl(var(--lozenge-in-progress))]",
    high: "text-[hsl(var(--lozenge-blocked))]",
  };

  return (
    <div className="h-full flex flex-col" data-testid={`kanban-board-${projectId}`}>
      <div className="flex gap-4 overflow-x-auto pb-4 flex-1">
        {columns.map((column) => {
          const columnTasks = getColumnTasks(column.id);

          return (
            <div key={column.id} className="flex-shrink-0 w-[280px] flex flex-col">
              <div className="bg-muted/50 rounded-t-lg px-3 py-2 border-b">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <h3 className="font-semibold text-sm uppercase text-muted-foreground tracking-wide">
                      {column.title}
                    </h3>
                    <Badge variant="secondary" className="h-5 px-1.5 text-xs font-normal">
                      {columnTasks.length}
                    </Badge>
                  </div>
                  <Button variant="ghost" size="icon" className="h-6 w-6">
                    <Plus className="h-3 w-3" />
                  </Button>
                </div>
              </div>

              <div className="flex-1 bg-muted/30 p-2 space-y-2 overflow-y-auto rounded-b-lg">
                {columnTasks.map((task) => (
                  <Card 
                    key={task.id} 
                    className="hover-elevate cursor-pointer group bg-card shadow-sm"
                    onClick={() => handleTaskClick(task)}
                    data-testid={`task-${task.id}`}
                  >
                    <CardHeader className="p-3 pb-2">
                      <div className="flex items-start gap-2">
                        <GripVertical className="h-4 w-4 text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity flex-shrink-0 mt-0.5" />
                        <div className="flex-1 min-w-0 space-y-2">
                          <div className="flex items-center justify-between gap-2">
                            <span className="text-xs font-mono text-primary font-medium">
                              {task.id}
                            </span>
                            <Button variant="ghost" size="icon" className="h-5 w-5 opacity-0 group-hover:opacity-100">
                              <MoreHorizontal className="h-3 w-3" />
                            </Button>
                          </div>
                          <p className="text-sm leading-snug line-clamp-3">
                            {task.title}
                          </p>
                        </div>
                      </div>
                    </CardHeader>

                    <CardContent className="p-3 pt-0">
                      <div className="flex items-center justify-between gap-2">
                        <div className="flex items-center gap-1">
                          <Badge 
                            variant="outline" 
                            className={`text-xs h-5 px-1.5 ${typeConfig[task.type].className}`}
                          >
                            {typeConfig[task.type].label}
                          </Badge>
                          {task.aiGenerated && (
                            <Badge 
                              variant="outline" 
                              className="text-xs h-5 px-1.5 bg-[hsl(var(--lozenge-done-bg))] text-[hsl(var(--lozenge-done))] border-[hsl(var(--lozenge-done))]"
                            >
                              AI
                            </Badge>
                          )}
                        </div>
                        <div className="flex items-center gap-2">
                          {task.storyPoints && (
                            <Badge variant="secondary" className="h-5 w-5 p-0 flex items-center justify-center text-xs">
                              {task.storyPoints}
                            </Badge>
                          )}
                          {task.assignee && (
                            <Avatar className="h-5 w-5">
                              <AvatarFallback className="text-xs">
                                {task.assignee}
                              </AvatarFallback>
                            </Avatar>
                          )}
                          <span className={`text-lg ${priorityColors[task.priority]}`}>
                            •
                          </span>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      <TaskDetailModal
        task={selectedTask}
        open={isModalOpen}
        onOpenChange={setIsModalOpen}
        onUpdateTask={(updatedTask) => {
          setSelectedTask(updatedTask);
        }}
      />
    </div>
  );
}

client/src/pages/NewProject.tsx.content:
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import Breadcrumbs from "@/components/Breadcrumbs";
import AIProcessingIndicator from "@/components/AIProcessingIndicator";
import { Sparkles, Zap, Info } from "lucide-react";
import { useState } from "react";

export default function NewProject() {
  const [projectName, setProjectName] = useState("");
  const [projectKey, setProjectKey] = useState("");
  const [requirements, setRequirements] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [stage, setStage] = useState("");

  const stages = [
    "Analyzing requirements...",
    "Generating architecture modules...",
    "Creating database schema...",
    "Breaking down into tasks...",
  ];

  const handleGenerate = () => {
    setIsProcessing(true);
    setProgress(0);
    setStage(stages[0]);

    const interval = setInterval(() => {
      setProgress((prev) => {
        const newProgress = prev + 5;
        const stageIndex = Math.floor(newProgress / 25);
        if (stageIndex < stages.length) {
          setStage(stages[stageIndex]);
        }

        if (newProgress >= 100) {
          clearInterval(interval);
          setTimeout(() => {
            setIsProcessing(false);
            console.log("Generation complete!");
          }, 500);
          return 100;
        }
        return newProgress;
      });
    }, 150);
  };

  return (
    <div className="max-w-[1400px] mx-auto">
      <div className="border-b border-border bg-card px-6 py-4">
        <Breadcrumbs items={[
          { label: "Projects", href: "/" },
          { label: "Create Project" }
        ]} />
        <h1 className="text-2xl font-semibold mt-3">Create AI-Powered Project</h1>
      </div>

      <div className="p-6 space-y-6">
        <Card>
          <CardHeader className="border-b">
            <CardTitle className="text-base font-semibold">Project Details</CardTitle>
          </CardHeader>
          <CardContent className="p-6 space-y-6">
            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <Label htmlFor="project-name">
                  Project Name <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="project-name"
                  placeholder="e.g., E-commerce Platform"
                  value={projectName}
                  onChange={(e) => setProjectName(e.target.value)}
                  data-testid="input-project-name"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="project-key">
                  Project Key <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="project-key"
                  placeholder="e.g., ECOM"
                  value={projectKey}
                  onChange={(e) => setProjectKey(e.target.value.toUpperCase())}
                  data-testid="input-project-key"
                  className="font-mono"
                  maxLength={10}
                />
                <p className="text-xs text-muted-foreground">
                  Used as a prefix for task IDs (e.g., ECOM-1, ECOM-2)
                </p>
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="requirements">
                Requirements <span className="text-destructive">*</span>
              </Label>
              <Textarea
                id="requirements"
                placeholder="Describe your project in detail. Include features, user types, integrations, and technical requirements..."
                className="min-h-[200px] resize-none"
                value={requirements}
                onChange={(e) => setRequirements(e.target.value)}
                data-testid="input-requirements"
              />
              <div className="flex items-start gap-2 p-3 bg-muted/50 rounded-lg">
                <Info className="h-4 w-4 text-primary mt-0.5 flex-shrink-0" />
                <div className="text-sm space-y-1">
                  <p className="font-medium">Tips for better results:</p>
                  <ul className="text-muted-foreground space-y-0.5 ml-4 list-disc">
                    <li>Specify key features and user flows</li>
                    <li>Mention any third-party integrations needed</li>
                    <li>Include technical requirements or constraints</li>
                    <li>Define user roles and permissions if applicable</li>
                  </ul>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>

        {isProcessing && (
          <AIProcessingIndicator
            stage={stage}
            progress={progress}
            substage={progress < 50 ? "Analyzing..." : "Generating..."}
          />
        )}

        <Card>
          <CardHeader className="border-b">
            <div className="flex items-center gap-2">
              <Sparkles className="h-5 w-5 text-primary" />
              <CardTitle className="text-base font-semibold">AI Generation Process</CardTitle>
            </div>
          </CardHeader>
          <CardContent className="p-6">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              {[
                { 
                  step: "1", 
                  title: "Analyze", 
                  desc: "AI analyzes your requirements and identifies key features" 
                },
                { 
                  step: "2", 
                  title: "Design", 
                  desc: "Generates optimal architecture with frontend, backend, and database modules" 
                },
                { 
                  step: "3", 
                  title: "Tasks", 
                  desc: "Breaks down implementation into actionable tasks with priorities" 
                },
                { 
                  step: "4", 
                  title: "Export", 
                  desc: "Provides complete JSON specification ready for export" 
                },
              ].map(({ step, title, desc }) => (
                <div key={step} className="space-y-2">
                  <div className="flex items-center gap-2">
                    <Badge variant="secondary" className="h-6 w-6 p-0 flex items-center justify-center">
                      {step}
                    </Badge>
                    <h3 className="font-semibold text-sm">{title}</h3>
                  </div>
                  <p className="text-xs text-muted-foreground leading-relaxed">
                    {desc}
                  </p>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        <div className="flex items-center justify-between pt-4 border-t">
          <Button variant="outline" data-testid="button-cancel">
            Cancel
          </Button>
          <Button
            onClick={handleGenerate}
            disabled={!projectName || !projectKey || !requirements || isProcessing}
            data-testid="button-generate"
            className="gap-2"
          >
            <Zap className="h-4 w-4" />
            Generate Project Architecture
          </Button>
        </div>
      </div>
    </div>
  );
}

